/*!
 * @file cdr_aux.h
 * fastcdr2 dispatches (de)serialization of a nested, non-primitive member (via Cdr::operator<</>>)
 * through the ADL customization points eprosima::fastcdr::serialize<T>/deserialize<T>, rather than
 * through a T::serialize(Cdr&) member function as fastcdr1 did. The message types below still only
 * define the member-function form, so provide the free-function specializations fastcdr2 looks for,
 * mirroring the companion "CdrAux" headers fastddsgen now generates for this purpose.
 *
 * Only needed by translation units that serialize one of these types as a member of another
 * (currently: Header.cpp, CameraInfo.cpp, Image.cpp, Imu.cpp).
 */

#ifndef _LIBREALSENSE_ROS2_MSG_TYPES_CDR_AUX_H_
#define _LIBREALSENSE_ROS2_MSG_TYPES_CDR_AUX_H_

#include <fastcdr/Cdr.h>
#include <builtin_interfaces/msg/Time.h>
#include <geometry_msgs/msg/Vector3.h>
#include <geometry_msgs/msg/Quaternion.h>
#include <std_msgs/msg/Header.h>
#include <sensor_msgs/msg/RegionOfInterest.h>

namespace eprosima {
namespace fastcdr {

template<> inline void serialize(Cdr& cdr, const builtin_interfaces::msg::Time& data) { data.serialize(cdr); }
template<> inline void deserialize(Cdr& cdr, builtin_interfaces::msg::Time& data) { data.deserialize(cdr); }

template<> inline void serialize(Cdr& cdr, const geometry_msgs::msg::Vector3& data) { data.serialize(cdr); }
template<> inline void deserialize(Cdr& cdr, geometry_msgs::msg::Vector3& data) { data.deserialize(cdr); }

template<> inline void serialize(Cdr& cdr, const geometry_msgs::msg::Quaternion& data) { data.serialize(cdr); }
template<> inline void deserialize(Cdr& cdr, geometry_msgs::msg::Quaternion& data) { data.deserialize(cdr); }

template<> inline void serialize(Cdr& cdr, const std_msgs::msg::Header& data) { data.serialize(cdr); }
template<> inline void deserialize(Cdr& cdr, std_msgs::msg::Header& data) { data.deserialize(cdr); }

template<> inline void serialize(Cdr& cdr, const sensor_msgs::msg::RegionOfInterest& data) { data.serialize(cdr); }
template<> inline void deserialize(Cdr& cdr, sensor_msgs::msg::RegionOfInterest& data) { data.deserialize(cdr); }

} // namespace fastcdr
} // namespace eprosima

#endif // _LIBREALSENSE_ROS2_MSG_TYPES_CDR_AUX_H_
